properties.property:
return function(self, dt)
    self.hotspots = {
        right_top = {x = self.x + 12, y = self.y + self.sprite.h/2 + 10},
        right_bot = {x = self.x + 12, y = self.y + self.sprite.h},
        left_top  = {x = self.x - 15, y = self.y + self.sprite.h/2 + 10},
        left_bot  = {x = self.x - 15, y = self.y + self.sprite.h}
    }
end
